css:
[data-ui-unit="tasks"] .task-row {
  min-height: 56px;
  display: flex;
  align-items: flex-start;
  gap: 8px;
}


[data-ui-unit="tasks"] .task-toggle {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 8px 0;
  min-height: 44px;
  cursor: pointer;
  flex: 1;
  min-width: 0;
}


[data-ui-unit="tasks"] .task-check {
  width: 20px;
  height: 20px;
  min-width: 20px;
  flex-shrink: 0;
  margin-top: calc(.8em - 10px);
  accent-color: var(--focus);
  cursor: pointer;
}


[data-ui-unit="tasks"] .task-name {
  flex: 1;
  min-width: 0;
  font-size: 16px;
  font-weight: 500;
  line-height: 1.6;
  word-break: keep-all;
  overflow-wrap: anywhere;
  color: var(--text);
}


[data-ui-unit="tasks"] .task-row.is-complete .task-name {
  color: var(--muted);
  text-decoration: line-through;
  opacity: 1;
}


[data-ui-unit="tasks"] .delete-task {
  width: auto;
  height: auto;
  min-width: 44px;
  min-height: 44px;
  border: none;
  color: var(--text);
  background: transparent;
  padding: 0 4px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  font-size: 16px;
  font-weight: 500;
  line-height: 1.5;
  cursor: pointer;
  white-space: normal;
  margin-top: max(0px, calc(0.8em - 14px));
}

[data-ui-unit="tasks"] .delete-task img {
  width: calc(1em + 4px);
  height: calc(1em + 4px);
  display: block;
}
